using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Non-static class — services are injected via constructor by the MCP SDK.
/// </summary>
[McpServerToolType]
public class ApiTools(IHttpClientFactory httpClientFactory, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Get a single post by its numeric ID.")]
    public async Task<string> GetPost(
        [Description("The post ID (1-100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var client = httpClientFactory.CreateClient("api");
        var post = await client.GetFromJsonAsync<JsonElement>(
            $"/posts/{id}", cancellationToken);
        return JsonSerializer.Serialize(post, JsonOptions);
    }

    [McpServerTool, Description("List posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter by user ID (omit for all posts)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var posts = await client.GetFromJsonAsync<JsonElement>(url, cancellationToken);
        return JsonSerializer.Serialize(posts, JsonOptions);
    }

    [McpServerTool(Destructive = false, ReadOnly = true),
     Description("Get all comments for a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to fetch comments for")] int postId,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("api");
        var comments = await client.GetFromJsonAsync<JsonElement>(
            $"/posts/{postId}/comments", cancellationToken);
        return JsonSerializer.Serialize(comments, JsonOptions);
    }

    [McpServerTool(Destructive = false, Idempotent = true),
     Description("Create a new post (simulated — JSONPlaceholder returns a fake response).")]
    public async Task<string> CreatePost(
        [Description("Title of the post")] string title,
        [Description("Body content of the post")] string body,
        [Description("User ID of the author")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);
        var client = httpClientFactory.CreateClient("api");
        var response = await client.PostAsJsonAsync("/posts",
            new { title, body, userId }, cancellationToken);
        response.EnsureSuccessStatusCode();
        var result = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(result, JsonOptions);
    }
}

